/**
 * speech.ts — Free voice AI via the browser-native Web Speech API.
 * ----------------------------------------------------------------------------
 * TTS: window.speechSynthesis speaks the phone agent's replies (which are
 *      generated by agentService → server AI when configured, local engine
 *      otherwise). Speaking state is reported through callbacks so the call
 *      screen can animate.
 * STT: window.SpeechRecognition || window.webkitSpeechRecognition transcribes
 *      the homeowner's side when the user presses the Microphone button.
 *
 * Hard requirements:
 *   - Feature-detect everything; never crash on unsupported browsers (Firefox,
 *     headless environments). Callers get `null` / `false` instead of throws.
 *   - Text input always remains as the fallback path in the UI.
 * ----------------------------------------------------------------------------
 */

/** True when text-to-speech is available in this browser. */
export function isSpeechSynthesisSupported(): boolean {
  try {
    return typeof window !== 'undefined' && 'speechSynthesis' in window;
  } catch {
    return false;
  }
}

/** The SpeechRecognition constructor (Chrome/Edge/Safari), or null. */
export function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
  try {
    const w = window as unknown as {
      SpeechRecognition?: new () => SpeechRecognitionLike;
      webkitSpeechRecognition?: new () => SpeechRecognitionLike;
    };
    return w.SpeechRecognition || w.webkitSpeechRecognition || null;
  } catch {
    return null;
  }
}

/** True when speech-to-text is available in this browser. */
export function isSpeechRecognitionSupported(): boolean {
  return getSpeechRecognitionCtor() !== null;
}

/** Any currently speaking utterance is cancelled. Safe to call always. */
export function stopSpeaking(): void {
  try {
    if (isSpeechSynthesisSupported()) window.speechSynthesis.cancel();
  } catch {
    /* non-fatal */
  }
}

/**
 * Speak `text` aloud. Resolves when playback ends (or immediately after an
 * error/unavailability) — never rejects, never throws.
 */
export function speakText(
  text: string,
  opts?: { onEnd?: () => void; onStart?: () => void }
): Promise<void> {
  return new Promise(resolve => {
    if (!isSpeechSynthesisSupported() || !text.trim()) {
      opts?.onEnd?.();
      resolve();
      return;
    }

    try {
      // Fresh utterance each time — reusing cancelled utterances is flaky.
      const utter = new SpeechSynthesisUtterance(text);
      utter.rate = 1.05;
      utter.pitch = 1;
      utter.volume = 1;
      // Prefer a natural English voice when one exists.
      const voices = window.speechSynthesis.getVoices();
      const preferred =
        voices.find(v => /en[-_]US/i.test(v.lang) && /female|samantha|zira|aria|jenny/i.test(v.name)) ||
        voices.find(v => /en[-_]US/i.test(v.lang)) ||
        voices.find(v => /^en/i.test(v.lang));
      if (preferred) utter.voice = preferred;

      let settled = false;
      const finish = () => {
        if (!settled) {
          settled = true;
          opts?.onEnd?.();
          resolve();
        }
      };
      utter.onstart = () => opts?.onStart?.();
      utter.onend = finish;
      utter.onerror = finish;
      // Safety valve: browsers occasionally never fire onend.
      window.setTimeout(finish, Math.max(4000, text.length * 90));

      window.speechSynthesis.speak(utter);
    } catch {
      opts?.onEnd?.();
      resolve();
    }
  });
}

/**
 * Start one-shot speech recognition. Calls `onFinal` with the final
 * transcript, `onError` with the error code (e.g. 'not-allowed'), and
 * `onEnd` when recognition stops. Returns a handle with `stop()`, or null
 * when unsupported. Never throws.
 */
export function startListening(handlers: {
  onFinal: (transcript: string) => void;
  onError?: (code: string) => void;
  onEnd?: () => void;
}): { stop: () => void } | null {
  const Ctor = getSpeechRecognitionCtor();
  if (!Ctor) return null;

  try {
    const rec = new Ctor();
    rec.lang = 'en-US';
    rec.continuous = false; // one utterance per mic press
    rec.interimResults = true;
    rec.maxAlternatives = 1;

    rec.onresult = (event: SpeechRecognitionEventLike) => {
      let finalText = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        const res = event.results[i];
        if (res.isFinal) {
          finalText += res[0]?.transcript ?? '';
        }
      }
      const trimmed = finalText.trim();
      if (trimmed) handlers.onFinal(trimmed);
    };
    rec.onerror = (event: SpeechRecognitionErrorEventLike) => handlers.onError?.(event.error);
    rec.onend = () => handlers.onEnd?.();

    rec.start();
    return { stop: () => { try { rec.stop(); } catch { /* already stopped */ } } };
  } catch {
    handlers.onError?.('unavailable');
    return null;
  }
}
